    // ══ (m) L'ÉCRAN DE CONNEXION : LA CAUSE NOMMÉE, PAS UN CORPS JSON TRANCHÉ ═══════════════════════
    const formulaire97 = $97("#login-form"), erreur97 = $97("#login-err");
