    // LE FREIN : quatre cent vingt-neuf nommé, délai servi — il se dit, avec le délai, et n'accuse pas le code.
    servis108["POST /api/mfa/disable"] = { statut: 429, reessai: "42", corps: { error: CAUSE_FREIN108 } };
