    const phraseActivation108 = (mod, cle, cause, delai) => mod.motDeLActivationMfa(cle, delai) + (cause ? " « " + cause + " »" : "");
    const v1108 = await verifier108(modIdp108, { statut: 401, corps: { error: "code TOTP invalide" } });
