      const tableTicket109 = [{ status: 401, cause: CAUSE_TICKET109 }, { status: 401, cause: "code MFA invalide" }, { status: 401 }, { status: 503, cause: CAUSE_TICKET109 }].map((r) => modConnexion109.cleDuRefusDuSecondFacteur(r)).join(",");
