        neuf: champs.find((c) => c.tagName === "INPUT" && c.autocomplete === "new-password"),
        actuel: champs.find((c) => c.tagName === "INPUT" && c.getAttribute("data-mot-de-passe-actuel") === "1") || null,
        enregistrer: champs.find((c) => c.tagName === "BUTTON"),
