    const clesDuCompteRendu113 = (((suppressionP113.match(/let compte_rendu = json!\(\{([\s\S]*?)\}\);/) || [])[1]) || "").match(/"(\w+)":/g) || [];
    const clesDesJetons113 = (((traitementP113.match(/pub\(crate\) fn en_json\(&self\) -> Value \{\s*json!\(\{([\s\S]*?)\}\)/) || [])[1]) || "").match(/"(\w+)":/g) || [];
